const validCPF = (c) => {
  if (c.length !== 11 || /^(\d)\1+$/.test(c)) return false;
  for (const t of [9, 10]) {
    let s = 0;
    for (let i = 0; i < t; i++) s += Number(c[i]) * (t + 1 - i);
    if (((s * 10) % 11) % 10 !== Number(c[t])) return false;
  }
  return true;
};

const mask = (txt) => String(txt || '')
  .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g,
           (m) => validCPF(m.replace(/\D/g, '')) ? '[CPF]' : m)
  .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[EMAIL]')
  .replace(/(?<!\d)(?:\+?55\s?)?\(?\d{2}\)?\s?9?\d{4}[-\s]?\d{4}(?!\d)/g, '[TELEFONE]');

const hoje = new Date().toISOString().slice(0, 10).replace(/-/g, '');

return $input.all().map((item) => ({
  json: {
    protocolo: 'RS-' + hoje + '-' + Math.floor(1000 + Math.random() * 9000),
    tipo_usuario: item.json.tipo_usuario,
    email: item.json.email,
    mensagem: mask(item.json.mensagem),
  },
}));

// Regras fixas: Prazos abaixo são ilustrativos, apenas para teste.
const regras = [
  { re: /fraude|golpe|clonad|invas[ãa]o|invadi|hack|n[ãa]o reconhe[çc]o/i, motivo: 'suspeita de fraude ou invasão', cor: 'vermelho' },
  { re: /reclame aqui|procon|processo|advogad|redes sociais|denunci|expor/i, motivo: 'risco de exposição pública', cor: 'vermelho' },
  { re: /reembolso|estorno|chargeback|saque|comiss[ãa]o|pagamento|cobran[çc]a|devolu[çc][ãa]o/i, motivo: 'envolve dinheiro', cor: 'amarelo' },
  { re: /\d{1,2}\s*(dias|semanas)|semanas?\b/i, motivo: 'espera longa relatada', cor: 'amarelo' },
];
const nomes = ['verde', 'amarelo', 'vermelho'];
const PRAZOS = { vermelho: 'até 2 horas úteis', amarelo: 'até 4 horas úteis', verde: 'até 1 dia útil' };
const dadoUtil = {
  comprador: 'o número do pedido',
  creator: 'o ID da venda ou o link que você divulgou',
  produtor: 'o ID do produto',
};

return $input.all().map((item) => {
  const j = item.json;
  const base = j.mensagem;
  const achadas = regras.filter((r) => r.re.test(base));
  const motivos = achadas.map((r) => r.motivo);
  const cor_regras = nomes[Math.max(0, ...achadas.map((r) => nomes.indexOf(r.cor)))];
  const prazo = PRAZOS[cor_regras];
  const msg = 'Olá! Recebemos a sua mensagem. Seu protocolo é ' + j.protocolo +
    '. Você terá uma resposta ' + prazo + '. Para agilizar, se tiver em mãos, ' +
    'informe ' + (dadoUtil[j.tipo_usuario] || 'os dados do caso') +
    '. Esta é uma mensagem automática; uma pessoa da nossa equipe vai acompanhar o seu caso.';
  return { json: { ...j, motivos, cor_regras, prazo_resposta: prazo, mensagem_confirmacao: msg } };
});

// Minimização: remove o e-mail antes de qualquer dado seguir para a IA.
return $input.all().map((item) => {
  const { email, mensagem_confirmacao, ...resto } = item.json;
  return { json: resto };
});

const base = $('Minimizar dados').first().json;
const ia = $json.output || {};

// Categorias que liberam o acesso aos logs. Ajuste aqui se quiser ampliar.
const CATEGORIAS_COM_LOGS = ['plataforma'];
const LIMITE_CONFIANCA = 0.6;

const nomes = ['verde', 'amarelo', 'vermelho'];
const corIA = nomes.includes(ia.cor) ? ia.cor : 'verde';
// A IA só pode AUMENTAR a urgência definida pelas regras, nunca reduzi-la.
const cor = nomes[Math.max(nomes.indexOf(base.cor_regras), nomes.indexOf(corIA))];

const confianca = typeof ia.confianca === 'number' ? ia.confianca : 0;
const categoria = ia.categoria || 'outro';
const incerto = confianca < LIMITE_CONFIANCA || categoria === 'outro';
const liberar_logs = CATEGORIAS_COM_LOGS.includes(categoria) && !incerto;

const resto = { ...base };
return [{ json: {
  ...resto,
  categoria,
  cor,
  cor_ia: corIA,
  confianca_classificacao: confianca,
  justificativa_classificacao: ia.justificativa || '',
  revisao_por_incerteza: incerto,
  liberar_logs,
} }];

const base = $('Decidir cor e liberar logs').first().json;
const out = $json.output || {};
const PRAZOS = { vermelho: 'até 2 horas úteis', amarelo: 'até 4 horas úteis', verde: 'até 1 dia útil' };

// A IA só pode AUMENTAR a urgência.
const cor = out.risco_exposicao_publica === true ? 'vermelho' : base.cor;
const escalar_humano = cor !== 'verde' || base.revisao_por_incerteza === true;
const conf = $('Regras de escalonamento').first().json;
let eventos_encontrados = 0;
try { eventos_encontrados = JSON.parse($('Buscar logs (simulado)').first().json.eventos_liberados).length; } catch (e) {}
const dadoUtil = {
  comprador: 'o número do pedido',
  creator: 'o ID da venda ou o link que você divulgou',
  produtor: 'o ID do produto',
};
const mensagem_confirmacao = 'Olá! Recebemos a sua mensagem. Seu protocolo é ' + base.protocolo +
  '. Você terá uma resposta ' + PRAZOS[cor] + '. Para agilizar, se tiver em mãos, ' +
  'informe ' + (dadoUtil[base.tipo_usuario] || 'os dados do caso') +
  '. Esta é uma mensagem automática; uma pessoa da nossa equipe vai acompanhar o seu caso.';

return [{ json: {
  protocolo: base.protocolo,
  email_cliente: conf.email,
  assunto_email: 'Recebemos sua mensagem - protocolo ' + base.protocolo,
  mensagem_confirmacao_enviada: mensagem_confirmacao,
  id_pseudonimo: base.id_pseudonimo,
  tipo_usuario: base.tipo_usuario,
  categoria: base.categoria,
  cor,
  prazo_resposta: PRAZOS[cor],
  escalar_humano,
  logs_consultados: base.liberar_logs,
  eventos_encontrados,
  revisao_por_incerteza: base.revisao_por_incerteza,
  confianca_classificacao: base.confianca_classificacao,
  motivos_regras: base.motivos,
  ...out,
} }];

// BASE SIMULADA de logs (dados fictícios). Em produção, isto seria uma consulta ao
// sistema de registros da empresa, com permissão restrita e só para esta conta.
// Este nó só executa quando a categoria é "plataforma" e a confiança é alta.
const BASE_LOGS = {
  'creator2@exemplo.com': [
    { evento: 'saque_solicitado', status: 'erro_validacao_conta', dias_atras: 0 },
    { evento: 'saque_solicitado', status: 'erro_validacao_conta', dias_atras: 0 },
    { evento: 'saque_solicitado', status: 'erro_validacao_conta', dias_atras: 0 },
  ],
  'produtor3@exemplo.com': [
    { evento: 'abertura_checkout', dispositivo: 'mobile', dias_atras: 1 },
    { evento: 'erro_script_checkout', codigo: 'JS-504', dispositivo: 'mobile', dias_atras: 1 },
  ],
  // Abaixo: contas que TÊM logs, mas cujos casos não são "plataforma" (logs não são consultados).
  'cliente1@exemplo.com': [
    { evento: 'compra_aprovada', dias_atras: 16 },
    { evento: 'cancelamento_solicitado', dias_atras: 14 },
  ],
  'cliente7@exemplo.com': [
    { evento: 'erro_script_checkout', codigo: 'JS-504', dispositivo: 'mobile', dias_atras: 1 },
  ],
  'creator5@exemplo.com': [
    { evento: 'login_novo_dispositivo', dias_atras: 1 },
    { evento: 'alteracao_dados_bancarios', dias_atras: 1 },
  ],
};

const email = String($('Regras de escalonamento').first().json.email || '').toLowerCase().trim();
const eventos = BASE_LOGS[email] || [];

return $input.all().map((item) => ({
  json: { ...item.json, eventos_liberados: JSON.stringify(eventos), eventos_encontrados: eventos.length },
}));
